import{az as r,P as a,Q as t,aQ as l}from"./chunks/framework.oHSDCGnP.js";import"./chunks/theme.SRuXo2Mz.js";const f=JSON.parse('{"title":"响应式","description":"","frontmatter":{},"headers":[],"relativePath":"框架/vue/vue/响应式.md","filePath":"框架/vue/vue/响应式.md","lastUpdated":1785249401000}'),o={name:"框架/vue/vue/响应式.md"};function i(n,e,s,h,c,p){return a(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="响应式" tabindex="-1">响应式 <a class="header-anchor" href="#响应式" aria-label="Permalink to “响应式”">​</a></h1><h2 id="vue3-如何实现响应式-proxy-和-object-defineproperty-的区别" tabindex="-1">Vue3 如何实现响应式（Proxy 和 Object.defineProperty 的区别） <a class="header-anchor" href="#vue3-如何实现响应式-proxy-和-object-defineproperty-的区别" aria-label="Permalink to “Vue3 如何实现响应式（Proxy 和 Object.defineProperty 的区别）”">​</a></h2><ol><li>Vue3 使用 Proxy，Proxy 代理是针对整个对象，而不是对象的某个属性，因此不同于 <code>Object.defineProperty</code> 的必须遍历对象每个属性，<code>Proxy</code> 只需要做一层代理就可以监听同级结构下的所有属性变化。当然对于深层结构，递归还是需要进行的。此外 Proxy 还支持代理数组变化。</li><li><code>Object.defineProperty</code> 在一个对象上定义一个新属性或者修改一个已经存在的属性，使用 getter/setter 监听这个属性的变化。<code>Object.defineProperty</code> 的缺陷有三个： <ul><li>不能监听数组的变化，需要使用函数拦截处理数组的 push、pop、shift、unshift、reverse、sort、splice 方法</li><li>必须遍历对象的每个属性</li><li>必须深层遍历嵌套的对象</li></ul></li></ol><h2 id="响应式原理" tabindex="-1">响应式原理 <a class="header-anchor" href="#响应式原理" aria-label="Permalink to “响应式原理”">​</a></h2><p>Vue 是通过数据劫持和订阅发布来进行深入响应的。</p><ul><li><strong>数据劫持（双向数据绑定）</strong>：通过 <code>Object.defineProperty</code> 的 getter/setter 监听数据的变化，同时 getter 也用于依赖收集，而 setter 在数据变更时通知订阅者更新视图。</li><li><strong>发布订阅模式</strong>：通过自定义事件将 data 的变化反映到视图上去。Vue 通过 Observer 观察者对象反应数据的变化，然后通知 Vue 生成新的 Virtual DOM，进而渲染视图。</li></ul><h2 id="观察者模式-observer-发布订阅模式" tabindex="-1">观察者模式（Observer / 发布订阅模式） <a class="header-anchor" href="#观察者模式-observer-发布订阅模式" aria-label="Permalink to “观察者模式（Observer / 发布订阅模式）”">​</a></h2><p>通过递归的方式把一个对象的所有属性都转化成可观测对象。</p><p>参考文章：</p><ul><li><a href="https://freesion.com/article/2571574110/" target="_blank" rel="noreferrer">https://freesion.com/article/2571574110/</a></li><li><a href="https://blog.csdn.net/xiaozidewawa/article/details/108381583" target="_blank" rel="noreferrer">https://blog.csdn.net/xiaozidewawa/article/details/108381583</a></li><li><a href="https://zhuanlan.zhihu.com/p/51357583" target="_blank" rel="noreferrer">https://zhuanlan.zhihu.com/p/51357583</a></li><li><a href="https://jianshu.com/p/594f018b68e7" target="_blank" rel="noreferrer">https://jianshu.com/p/594f018b68e7</a></li><li><a href="https://cnblogs.com/fundebug/p/responsive-vue.html" target="_blank" rel="noreferrer">https://cnblogs.com/fundebug/p/responsive-vue.html</a></li><li><a href="https://cnblogs.com/liaohuihui/p/11269052.html" target="_blank" rel="noreferrer">https://cnblogs.com/liaohuihui/p/11269052.html</a></li></ul><h2 id="相关源码" tabindex="-1">相关源码 <a class="header-anchor" href="#相关源码" aria-label="Permalink to “相关源码”">​</a></h2><ul><li><a href="./源码片段/proxy">响应式源码片段</a></li><li><a href="./源码片段/observer">observer 源码片段</a></li></ul>',12)])])}const b=r(o,[["render",i]]);export{f as __pageData,b as default};
